theorem Ginv_eq_on_V (sD sJ sD' sJ' : PlaqSel) (hsD : ∀ (L : PeriodicLatticeExtent) (G : TowerGeom L), plaqIn G.Om0 ⊆ sD L G)
    (hsD' : ∀ (L : PeriodicLatticeExtent) (G : TowerGeom L), plaqIn G.Om0 ⊆ sD' L G) {x : ↥(bondSupp P.G)}
    (hx : x ∈ V0 P.G) : (dataS sD sJ P).Ginv x = (dataS sD' sJ' P).Ginv x

theorem G1inv_coercive (hL : D.Laws) {G1inv : E →L[ℝ] E} (hG : D.IsG1inv G1inv) {c ε : ℝ}
    (hc : ∀ x, c * ‖x‖ ^ 2 ≤ ⟪x, D.Ginv x⟫) (hε : ‖D.Delta2 hL‖ ≤ ε) :
    ∀ x, (c - ε) * ‖x‖ ^ 2 ≤ ⟪x, G1inv x⟫

theorem isUnit_of_desc [Nonempty D] {O : PiLp 2 (fun _ : X => E) →L[ℝ] PiLp 2 (fun _ : X => E)}
    {Ot' : PiLp 2 (fun _ : Xt => E) →L[ℝ] PiLp 2 (fun _ : Xt => E)}
    (h : E1 cX cX O Ot') (hu : IsUnit Ot') : IsUnit O

theorem Desc.inverse [Nonempty D] {O : PiLp 2 (fun _ : X => E) →L[ℝ] PiLp 2 (fun _ : X => E)}
    {Ot : PiLp 2 (fun _ : Xt => E) →L[ℝ] PiLp 2 (fun _ : Xt => E)} (h : Desc cX cX O Ot) (hu : IsUnit Ot) :
    IsUnit O ∧ Desc cX cX (Ring.inverse O) (Ring.inverse Ot)

theorem H0_congr_rows {Lu : PeriodicLatticeExtent} {ell : ℕ} (Lam : Set (PeriodicLatticeSite Lu))
    {Q Q' : (Bond Lu → SuTwo) →ₗ[ℝ] (CoarseBond Lu ell → SuTwo)}
    (h : ∀ B c, CRowIn ell Lam c → Q B c = Q' B c) : H0 Lam Q = H0 Lam Q'

theorem hLift_congr_rows {Lu : PeriodicLatticeExtent} {ell : ℕ} (Lam : Set (PeriodicLatticeSite Lu))
    {Q Q' : (Bond Lu → SuTwo) →ₗ[ℝ] (CoarseBond Lu ell → SuTwo)}
    (h : ∀ B c, CRowIn ell Lam c → Q B c = Q' B c) {f f' : CoarseBond Lu ell → SuTwo}
    (hf : ∀ c, CRowIn ell Lam c → f c = f' c) : hLift Lam Q f = hLift Lam Q' f'

theorem RImage_support {ell k : ℕ} (S : Tower L) (U : Cfg L) {v : SiteL2 L}
    (hv : v ∈ RImage (geomOf ell k S) U) (x : PeriodicLatticeSite L)
    (hx : ∀ y ∈ Ball x 1, y ∉ S.Om 1) : v x = 0
